'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const heights = input.slice(1);
const order = Array.from({ length: n }, (_, i) => i);
order.sort((a, b) => heights[b] - heights[a]);

const parent = new Int32Array(n);
const size = new Int32Array(n);
const active = new Uint8Array(n);

for (let i = 0; i < n; i++) {
  parent[i] = i;
  size[i] = 1;
}

function find(x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function union(a, b) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return false;

  if (size[ra] < size[rb]) {
    const temp = ra;
    ra = rb;
    rb = temp;
  }

  parent[rb] = ra;
  size[ra] += size[rb];
  return true;
}

let components = 0;
let maxComponents = 0;

for (let i = 0; i < n;) {
  let j = i;
  while (j < n && heights[order[j]] === heights[order[i]]) j++;

  for (let k = i; k < j; k++) {
    const index = order[k];
    active[index] = 1;
    components++;
    if (index > 0 && active[index - 1] && union(index, index - 1)) components--;
    if (index + 1 < n && active[index + 1] && union(index, index + 1)) components--;
  }

  maxComponents = Math.max(maxComponents, components);
  i = j;
}

console.log(maxComponents + 1);
